from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user
from src.backend.db.session import get_db
from src.backend.models.client_feedback import ClientFeedback
from src.backend.models.user import User
from src.backend.schemas.client_feedback import (
    ClientFeedbackCreate,
    ClientFeedbackListResponse,
    ClientFeedbackRead,
    ClientFeedbackUpdate,
)
from src.backend.services import client_feedback_service

router = APIRouter(prefix="/api/client-feedback", tags=["client-feedback"])


@router.get("", response_model=ClientFeedbackListResponse)
def list_client_feedback(
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> ClientFeedbackListResponse:
    items, total = client_feedback_service.list_client_feedback_service(
        db, page=page, page_size=page_size
    )
    return ClientFeedbackListResponse(
        items=[ClientFeedbackRead.model_validate(i) for i in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=ClientFeedbackRead, status_code=status.HTTP_201_CREATED)
def create_client_feedback(
    body: ClientFeedbackCreate,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ClientFeedbackRead:
    feedback = client_feedback_service.create_client_feedback_service(
        db, body, current_user.id
    )
    return ClientFeedbackRead.model_validate(feedback)


@router.get("/{feedback_id}", response_model=ClientFeedbackRead)
def get_client_feedback(
    feedback_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ClientFeedbackRead:
    feedback = client_feedback_service.get_client_feedback_service(db, feedback_id)
    if not feedback:
        raise HTTPException(status_code=404, detail="Client feedback not found")
    return ClientFeedbackRead.model_validate(feedback)


@router.patch("/{feedback_id}", response_model=ClientFeedbackRead)
def update_client_feedback(
    feedback_id: uuid.UUID,
    body: ClientFeedbackUpdate,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ClientFeedbackRead:
    feedback = client_feedback_service.update_client_feedback_service(
        db, feedback_id, body, current_user.id
    )
    if not feedback:
        raise HTTPException(status_code=404, detail="Client feedback not found")
    return ClientFeedbackRead.model_validate(feedback)


@router.delete("/{feedback_id}", status_code=status.HTTP_204_NO_CONTENT, response_class=None)
def delete_client_feedback(
    feedback_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
):
    ok = client_feedback_service.delete_client_feedback_service(
        db, feedback_id, current_user.id
    )
    if not ok:
        raise HTTPException(status_code=404, detail="Client feedback not found")
    return None

