import type { Client } from "@/types/api";

export interface ClientFeedback {
  id: string;
  feedback_id: string;
  date: string;
  client_id: string;
  client?: Client;
  reference_type: string;
  reference_id: string | null;
  overall_rating: number;
  quality_rating: number;
  timeliness_rating: number;
  communication_rating: number;
  would_recommend: boolean;
  comments: string | null;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
}

export interface ClientFeedbackListResponse {
  items: ClientFeedback[];
  total: number;
  page: number;
  page_size: number;
}

export interface ClientFeedbackCreate {
  feedback_id: string;
  date: string;
  client_id: string;
  reference_type: string;
  reference_id: string | null;
  overall_rating: number;
  quality_rating: number;
  timeliness_rating: number;
  communication_rating: number;
  would_recommend: boolean;
  comments: string | null;
}

export interface ClientFeedbackUpdate {
  feedback_id?: string;
  date?: string;
  client_id?: string;
  reference_type?: string;
  reference_id?: string;
  overall_rating?: number;
  quality_rating?: number;
  timeliness_rating?: number;
  communication_rating?: number;
  would_recommend?: boolean;
  comments?: string | null;
}

export type ComplaintStatus =
  | "Open"
  | "Investigating"
  | "Resolved"
  | "Closed"
  | "Rejected";

export type ComplaintSeverity = "Low" | "Medium" | "High" | "Critical";

export type ComplaintType =
  | "Quality"
  | "Timeliness"
  | "Communication"
  | "Billing"
  | "Scope"
  | "Other";

export type ReferenceType = "Project" | "Agreement" | "Token" | "DRN" | "Other";

export interface ClientComplaint {
  id: string;
  complaint_id: string;
  date_raised: string;
  client_id: string;
  client?: Client;
  reference_type: ReferenceType;
  reference_id: string | null;
  complaint_type: ComplaintType;
  severity: ComplaintSeverity;
  description: string | null;
  root_cause: string | null;
  status: ComplaintStatus;
  owner_id: string | null;
  closure_date: string | null;
  notes: string | null;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
}

export interface ClientComplaintListResponse {
  items: ClientComplaint[];
  total: number;
  page: number;
  page_size: number;
}

export interface ClientComplaintCreate {
  complaint_id: string;
  date_raised: string;
  client_id: string;
  reference_type: ReferenceType;
  reference_id: string | null;
  complaint_type: ComplaintType;
  severity: ComplaintSeverity;
  description: string | null;
  root_cause: string | null;
  status: ComplaintStatus;
  owner_id: string | null;
  closure_date: string | null;
  notes: string | null;
}

export interface ClientComplaintUpdate {
  complaint_id?: string;
  date_raised?: string;
  client_id?: string;
  reference_type?: ReferenceType;
  reference_id?: string;
  complaint_type?: ComplaintType;
  severity?: ComplaintSeverity;
  description?: string | null;
  root_cause?: string | null;
  status?: ComplaintStatus;
  owner_id?: string | null;
  closure_date?: string | null;
  notes?: string | null;
}

import type {
  ClientFeedback,
  ClientFeedbackListResponse,
  ClientFeedbackCreate,
  ClientFeedbackUpdate,
  ClientComplaint,
  ClientComplaintListResponse,
  ClientComplaintCreate,
  ClientComplaintUpdate,
} from "@/types/crm";
import { request } from "./api";

export const crmApi = {
  listClientFeedback: (params?: {
    page?: number;
    page_size?: number;
  }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    const query = searchParams.toString();
    return request<ClientFeedbackListResponse>(
      `/api/client-feedback${query ? `?${query}` : ""}`
    );
  },

  getClientFeedback: (id: string) =>
    request<ClientFeedback>(`/api/client-feedback/${id}`),

  createClientFeedback: (data: ClientFeedbackCreate) =>
    request<ClientFeedback>("/api/client-feedback", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateClientFeedback: (id: string, data: ClientFeedbackUpdate) =>
    request<ClientFeedback>(`/api/client-feedback/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteClientFeedback: (id: string) =>
    request<void>(`/api/client-feedback/${id}`, { method: "DELETE" }),

  listClientComplaints: (params?: {
    page?: number;
    page_size?: number;
    severity?: string;
  }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.severity) searchParams.set("severity", params.severity);
    const query = searchParams.toString();
    return request<ClientComplaintListResponse>(
      `/api/client-complaints${query ? `?${query}` : ""}`
    );
  },

  getClientComplaint: (id: string) =>
    request<ClientComplaint>(`/api/client-complaints/${id}`),

  createClientComplaint: (data: ClientComplaintCreate) =>
    request<ClientComplaint>("/api/client-complaints", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateClientComplaint: (id: string, data: ClientComplaintUpdate) =>
    request<ClientComplaint>(`/api/client-complaints/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteClientComplaint: (id: string) =>
    request<void>(`/api/client-complaints/${id}`, { method: "DELETE" }),

  resolveClientComplaint: (id: string) =>
    request<ClientComplaint>(`/api/client-complaints/${id}`, {
      method: "PATCH",
      body: JSON.stringify({ status: "Resolved" }),
    }),

  closeClientComplaint: (id: string) =>
    request<ClientComplaint>(`/api/client-complaints/${id}`, {
      method: "PATCH",
      body: JSON.stringify({ status: "Closed" }),
    }),
};
